            return Served::Now(self.remote_command(request, &device, session, verb));
        }
        ("POST", ["projects", project, "sessions"]) => {
            return Served::Now(self.remote_new_session(request, &device, project));
        }
        ("GET" | "POST", ["sessions", session, "draft"]) => {
            return Served::Now(self.remote_draft(request, &device, session));
        }
        ("POST", ["sessions", session, "dictation"]) => {
            return Served::Now(self.remote_dictation(request, &device, session));
        }
        ("GET", ["dispatch", "tickets"]) => return Served::Now(self.remote_tickets(request)),
        ("GET", ["dispatch", "tickets", ticket]) => {
            return Served::Now(self.remote_ticket(request, ticket));
        }
        (
            "POST",
            [
                "dispatch",
                "tickets",
                ticket,
                verb @ ("decide" | "resume" | "close"),
            ],
        ) => {
            return self.remote_ticket_command(request, &device, ticket, verb, reply);
        }
        ("GET", ["dispatch", "tickets", ticket, "events"]) => {
            return self.remote_ticket_events(request, ticket, reply);
        }
        ("GET", ["dispatch", "tickets", ticket, "files", key]) => {
            return self.remote_ticket_file(request, ticket, key, reply);
        }
        (
            "GET",
            ["sessions", _, "screen" | "conversation" | "last-response"]
            | ["sessions", _, "conversation", _]
            | ["sessions", _, "runs", _, "output"]
            | ["projects", _, "files", _, ..],
        ) => {
            return self.remote_content_route(request, &segments, reply);
        }
        _ => {
            return Served::Now(self.refuse(
                request,
                404,
                "not_found",
                "not available on this port",
                true,
            ));
        }
    };
    let mut reply = self.answer(&body);
    if request.param("scope") != Some("all") {
        Self::hide_workers(&mut reply);
    }
    Served::Now(self.remote_reply(request, &reply, notes_cap))
}

/// The paired device behind a request's bearer token, seen now; or
/// the refusal, which says nothing of the host.
fn authenticate(&mut self, request: &RemoteRequest) -> Result<PairedDevice, RemoteReply> {
    let Some(token) = &request.bearer else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "pair this device first",
            false,
        ));
    };
    let Some(device) = self
        .core
        .device_by_token(&remote::token_sha256(token))
        .cloned()
    else {
        return Err(self.refuse(
            request,
            401,
            "unauthorized",
            "the token is not known; pair again",
            false,
        ));
    };
    self.dispatch_inner(AppAction::DeviceSeen(device.id));
    Ok(device)
}

/// A command under `control` scope. The body's `op` is the operation
/// id the device made, which is the idempotency key: the command
/// goes through `serve` as the control socket's do, so a send or a
/// resume is logged before it runs and a repeat of the op is
/// answered from the log without running again (§4.5).
fn remote_command(
    &mut self,
    request: &RemoteRequest,
    device: &PairedDevice,
    session: &str,
    verb: &str,
) -> RemoteReply {
    if device.scope != Scope::Control {
        return self.refuse(
            request,
            403,
            "scope",
            "this device reads only; raise its scope on the host",
            true,
        );
    }
    let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {

            Err(mpsc::TrySendError::Disconnected(_)) => false,
        }
    });
}

/// Accept a device's subscription: `hello` with the revision as it
/// stands goes into the queue first, so a snapshot the device takes
/// after it can be reconciled against everything that follows.
fn remote_subscribe(
    &mut self,
    request: &RemoteRequest,
    device: uuid::Uuid,
    subscriber: Option<SubscriberQueue>,
) -> RemoteReply {
    let Some(queue) = subscriber.filter(|_| request.upgrade.is_some()) else {
        return self.refuse(
            request,
            400,
            "upgrade_required",
            "events are a WebSocket; upgrade the connection",
            true,
        );
    };
    let hello = self.event_json("hello", None, epoch_millis(SystemTime::now()));
    if queue.tx.try_send(hello).is_err() {
        return self.refuse(
            request,
            503,
            "busy",
            "the subscription could not start",
            true,
        );
    }
    self.subscribers.push(Subscriber {
        id: queue.id,
        queue,
        device,
        all: request.param("scope") == Some("all"),
    });
    RemoteReply {
        status: remote::SUBSCRIBED,
        body: Vec::new(),
        authenticated: true,
    }
}

/// How many devices are subscribed to events.
#[must_use]
pub fn subscriber_count(&self) -> usize {
    self.subscribers.len()
}
    for id in moved {
        let text = self.event_json("changed", Some(("draft", &id.0.to_string())), at_ms);
        self.broadcast(&text, false);
    }
}

/// Who this host is, to anyone: nothing in it is a secret and
/// nothing in it is trusted until the key is pinned.
fn remote_info(&self) -> RemoteReply {
    let Some(identity) = self.core.identity() else {
        return RemoteReply {
            status: 503,
            body: self.error_json("no_identity", "the host has no identity yet"),
            authenticated: false,
        };
    };
    let body = serde_json::json!({
        "server_id": identity.server_id,
        "server_name": identity.server_name,
        "protocol": REMOTE_PROTOCOL,
        "capabilities": ["read", "control", "draft", "scope", "tickets", "evidence", "create"],
        "spki_sha256": identity.spki_sha256,
        "version": self.core.version(),
        "limits": {
            "body_bytes": BODY_CAP,
            "string_bytes": STRING_CAP,
            "notes_bytes": NOTES_CAP_ALONE,
            "screen_lines": SCREEN_LINES_CAP,
            "run_lines": RUN_LINES_CAP,
            "conversation_turns": PAGE_TURNS_CAP,
            "turn_bytes": TURN_BYTES_CAP,
            "activity_bytes": ACTIVITY_BYTES_CAP,
            "send_bytes": SEND_BYTES_CAP,
            "op_chars": OP_CAP,
            "file_bytes": FILE_BYTES_CAP,
        },
        "pairing_open": self.core.pairing_at(self.clock()).is_some(),
    });
    self.envelope(200, &body, false)
}

/// The pairing handshake: inside the window, with the host's own
/// key hash (so a request relayed through a substituted
/// certificate fails even with the code) and the code. A match
/// makes a token the device keeps and the host stores only the hash
/// of; a mismatch counts against the window.
fn remote_pair(&mut self, request: &RemoteRequest) -> RemoteReply {
    let now = self.clock();
    let Some(window) = self.core.pairing_at(now).cloned() else {
        return self.refuse(
            request,
            403,
            "pairing_closed",
            "pairing is not open on the host",
            false,
        );
    };
    let Some(identity) = self.core.identity().cloned() else {
        return self.refuse(
            request,
            503,
            "no_identity",
            "the host has no identity",
            false,
        );
    };
    let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {
        return self.refuse(request, 400, "bad_request", "the body is not JSON", false);
    };
    let field = |name: &str| {
        body.get(name)
            .and_then(|v| v.as_str())
            .unwrap_or("")
            .trim()
            .to_owned()
    };
    if field("spki_sha256") != identity.spki_sha256 {
        self.dispatch_inner(AppAction::PairingFailed);
        return self.refuse(
            request,
            403,
            "wrong_key",
            "this is not the host whose code was scanned",
            false,
        );
    }
    if field("code").to_ascii_uppercase() != window.code {
        self.dispatch_inner(AppAction::PairingFailed);
        return self.refuse(request, 403, "wrong_code", "the code does not match", false);
    }
    let name = field("device_name");
    let name = if name.is_empty() {
        "Device"
    } else {
        name.as_str()
    };
    let token = remote::bearer_token();
    let device = self
        .core
        .new_device(name, remote::token_sha256(&token), now.wall);
    let reply = serde_json::json!({
        "token": token,
        "scope": device.scope,
        "server_id": identity.server_id,
        "device_id": device.id,
    });
    log::info!(
        "remote: paired {:?} with {} scope",
        device.name,
        device.scope.word()
    );
    self.dispatch_inner(AppAction::Paired(device));
    self.envelope(200, &reply, false)
}

/// One working set with its pins, found across every space.
fn remote_set(&self, request: &RemoteRequest, set: &str) -> RemoteReply {
    let found = parse_uuid("set", set).ok().and_then(|id| {
        self.core
            .space_views()
            .iter()
        "epoch": self.epoch,
        "revision": self.revision,
        "error": { "code": code, "message": message },
    })
    .to_string()
    .into_bytes()
}

/// A refusal, logged by method, path and code only.
fn refuse(
    &self,
    request: &RemoteRequest,
    status: u16,
    code: &str,
    message: &str,
    authenticated: bool,
) -> RemoteReply {
    log::info!(
        "remote: {} {} refused: {code}",
        request.method,
        request.path
    );
    RemoteReply {
        status,
        body: self.error_json(code, message),
        authenticated,
    }
}

/// One request, one reply. A query reads; a command runs through the
/// core under its operation id, and its reply is logged so a repeat
/// of the same id is answered from the log without running again.
fn serve(&mut self, request: &wire::Request) -> wire::Reply {
    if !request.body.is_command() {
        return self.answer(&request.body);
    }

//! The remote port's state: the host's identity, the devices paired
//! with it, and the pairing window. Random material (the code, a
//! token) is made outside and arrives in the action; here it is only
//! compared and kept, so every transition is a plain function of its
//! inputs.

use std::time::SystemTime;

use uuid::Uuid;

use super::action::PairingWindow;
use super::action::{AppAction, AppCore, Clock, Effect, Out, PAIRING_ATTEMPTS, PAIRING_WINDOW};
use crate::ports::remote::{Identity, PairedDevice, Scope};

/// A device's last-seen time is saved when it moved by at least this
/// much, so a polling device does not rewrite `devices.json` on every
/// request.
const LAST_SEEN_SAVE_INTERVAL_SECS: u64 = 300;

impl AppCore {
    pub(super) fn remote_action(&mut self, action: AppAction, now: Clock, out: &mut Out) {
        match action {
            AppAction::IdentityLoaded {
                identity,
                devices,
                rotated,
            } => {
                self.identity = Some(identity);
                self.devices = devices;
                self.identity_rotated_at = rotated.then_some(now.mono);
            }
            AppAction::SetServerName(name) => {
                let name = name.trim().to_owned();
                if !name.is_empty() {
                    self.update_identity(out, |i| i.server_name = name);
                }
            }
            AppAction::SetRemoteListen { lan, port } => {
                if port != 0 {
                    self.update_identity(out, |i| {
                        i.listen.lan = lan;
                        i.listen.port = port;
                    });
                }
            }
            AppAction::OpenPairing { code, scope } => {
                // Typed by hand on the device, so case never matters.
                self.pairing = Some(PairingWindow {
                    until: now.mono + PAIRING_WINDOW,
                    code: code.trim().to_ascii_uppercase(),
                    scope,
                    failures: 0,
                });
            }
            AppAction::ClosePairing => self.pairing = None,
            AppAction::PairingFailed => {
                if let Some(p) = &mut self.pairing {
                    p.failures += 1;
                    if p.failures >= PAIRING_ATTEMPTS {
                        self.pairing = None;
                        self.error("Pairing closed: three attempts failed.");
                    }
                }
            }
            AppAction::Paired(device) => {
                // The code is single-use: the window closes with the
                // first pairing made through it.
                self.pairing = None;
                self.devices.push(device);
                self.save_devices(out);
            }
            AppAction::DeviceSeen(id) => {
                let Some(device) = self.devices.iter_mut().find(|d| d.id == id) else {
                    return;
                };
                let stale = device.last_seen.is_none_or(|seen| {
                    now.wall
                        .duration_since(seen)
                        .is_ok_and(|d| d.as_secs() >= LAST_SEEN_SAVE_INTERVAL_SECS)
                });
                device.last_seen = Some(now.wall);
                if stale {
                    self.save_devices(out);
                }
            }
            AppAction::RevokeDevice(id) => {
                let before = self.devices.len();
                self.devices.retain(|d| d.id != id);
                if self.devices.len() != before {
                    self.save_devices(out);
                }
            }
            AppAction::SetDeviceScope { device, scope } => {
                if let Some(d) = self.devices.iter_mut().find(|d| d.id == device)
                    && d.scope != scope
                {
                    d.scope = scope;
                    self.save_devices(out);
                }
            }
            _ => unreachable!("dispatched by `dispatch` itself"),
        }
    }

    fn update_identity(&mut self, out: &mut Out, change: impl FnOnce(&mut Identity)) {
        let Some(identity) = &self.identity else {
            return;
        };
        let mut next = identity.clone();
        change(&mut next);
        if Some(&next) != self.identity.as_ref() {
            self.identity = Some(next.clone());
            if !self.read_only {
                out.push(Effect::SaveIdentity(next));
            }
        }
    }

    fn save_devices(&self, out: &mut Out) {
        if !self.read_only {
            out.push(Effect::SaveDevices(self.devices.clone()));
        }
    }

    /// The host's identity, once loaded.
    #[must_use]
    pub fn identity(&self) -> Option<&Identity> {
        self.identity.as_ref()
    }

    /// The key was remade at this launch: every earlier pairing is gone.
    #[must_use]
    pub fn identity_rotated(&self) -> bool {
        self.identity_rotated_at.is_some()
    }

    /// The devices paired with this host.
    #[must_use]
    pub fn devices(&self) -> &[PairedDevice] {
        &self.devices
    }

    /// The device holding the token with this hash.
    #[must_use]
    pub fn device_by_token(&self, token_sha256: &str) -> Option<&PairedDevice> {
        self.devices.iter().find(|d| d.token_sha256 == token_sha256)
    }

    /// The pairing window, while it is open at `now`. `Tick` clears a
    /// passed one; between ticks this checks the time itself.
    #[must_use]
    pub fn pairing_at(&self, now: Clock) -> Option<&PairingWindow> {
        self.pairing.as_ref().filter(|p| p.until > now.mono)
    }

    /// The pairing window as last set, passed or not; the dialog uses
    /// `pairing_at` and this is for tests.
    #[must_use]
    pub fn pairing(&self) -> Option<&PairingWindow> {
        self.pairing.as_ref()
    }

    /// A device record for a pairing that matched: the window's scope,
    /// the token's hash, and the time.
    #[must_use]
    pub fn new_device(&self, name: &str, token_sha256: String, at: SystemTime) -> PairedDevice {
        PairedDevice {
            id: Uuid::new_v4(),
            name: name.trim().chars().take(64).collect(),
            scope: self.pairing.as_ref().map_or(Scope::Read, |p| p.scope),
            token_sha256,
            created: at,
            last_seen: None,
        }
    }
}

